CREATE EXTENSION IF NOT EXISTS vector;
CREATE TABLE IF NOT EXISTS creators (id uuid PRIMARY KEY, org_id text NOT NULL, platform text NOT NULL, platform_creator_id text NOT NULL, display_name text, profile jsonb NOT NULL DEFAULT '{}', embedding vector(1536), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(org_id,platform,platform_creator_id));
CREATE TABLE IF NOT EXISTS creator_profiles (id uuid PRIMARY KEY, creator_id uuid NOT NULL REFERENCES creators(id), version integer NOT NULL, status text NOT NULL DEFAULT 'draft', dna jsonb NOT NULL, evidence jsonb NOT NULL DEFAULT '[]', corrected_by text, correction_note text, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(creator_id,version));
CREATE TABLE IF NOT EXISTS distillation_tasks (id uuid PRIMARY KEY, org_id text NOT NULL, creator_url text NOT NULL, platform text NOT NULL, range_days integer, sample_count integer NOT NULL DEFAULT 50, status text NOT NULL, stage text NOT NULL, progress integer NOT NULL DEFAULT 0, error_category text, error_message text, degraded_reason text, capabilities jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS videos (id uuid PRIMARY KEY, creator_id uuid REFERENCES creators(id), task_id uuid REFERENCES distillation_tasks(id), platform text NOT NULL, asset_type text NOT NULL, source_id text NOT NULL, source_url text, title text, published_at timestamptz, metrics jsonb NOT NULL DEFAULT '{}', provenance jsonb NOT NULL, analysis jsonb NOT NULL DEFAULT '{}', performance_score numeric, sample_role text, capabilities jsonb NOT NULL DEFAULT '{}', degraded_reason text, embedding vector(1536), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(platform,source_id));
CREATE TABLE IF NOT EXISTS transcript_segments (id uuid PRIMARY KEY, video_id uuid NOT NULL REFERENCES videos(id), start_ms integer, end_ms integer, text text, function_label text, confidence numeric, provenance jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS shots (id uuid PRIMARY KEY, video_id uuid NOT NULL REFERENCES videos(id), start_ms integer, end_ms integer, shot_type text, semantic jsonb, confidence numeric, provenance jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS ocr_segments (id uuid PRIMARY KEY, video_id uuid NOT NULL REFERENCES videos(id), start_ms integer, end_ms integer, text text, region jsonb, ocr_type text, confidence numeric, provenance jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS comment_insights (id uuid PRIMARY KEY, video_id uuid NOT NULL REFERENCES videos(id), insight_type text, body jsonb NOT NULL, source_comment_ids jsonb NOT NULL DEFAULT '[]', confidence numeric, provenance jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS content_tags (id uuid PRIMARY KEY, parent_id uuid REFERENCES content_tags(id), tag_type text NOT NULL, name text NOT NULL, UNIQUE(tag_type,name));
CREATE TABLE IF NOT EXISTS evidence (id uuid PRIMARY KEY, video_id uuid REFERENCES videos(id), creator_profile_id uuid REFERENCES creator_profiles(id), evidence_type text NOT NULL, start_ms integer, end_ms integer, quote_text text, frame_url text, comment_id text, confidence numeric NOT NULL, provenance jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS style_profiles (id uuid PRIMARY KEY, creator_profile_id uuid NOT NULL REFERENCES creator_profiles(id), category text NOT NULL, judgment jsonb NOT NULL, confidence numeric NOT NULL, evidence_ids uuid[] NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS script_templates (id uuid PRIMARY KEY, title text NOT NULL, structure jsonb NOT NULL, source_creator_ids uuid[] NOT NULL DEFAULT '{}', evidence_ids uuid[] NOT NULL DEFAULT '{}', embedding vector(1536), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS raw_api_responses (id uuid PRIMARY KEY, task_id uuid REFERENCES distillation_tasks(id), platform text NOT NULL, endpoint text NOT NULL, endpoint_version text NOT NULL, status_code integer, response jsonb, fetched_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_distillation_tasks_status ON distillation_tasks(org_id,status,updated_at DESC);
CREATE INDEX IF NOT EXISTS idx_videos_creator_score ON videos(creator_id,performance_score DESC);
CREATE INDEX IF NOT EXISTS idx_videos_analysis_gin ON videos USING gin(analysis);
CREATE INDEX IF NOT EXISTS idx_evidence_video_time ON evidence(video_id,start_ms);
CREATE INDEX IF NOT EXISTS idx_creators_embedding ON creators USING hnsw (embedding vector_cosine_ops);
CREATE INDEX IF NOT EXISTS idx_videos_embedding ON videos USING hnsw (embedding vector_cosine_ops);
